 28	
 29	/*
 30	 * eval_expr - arithmetic expression evaluator
 31	 * by Stefan Strack, version 3 (pMARS v0.4.0+)
 32	 *
 33	 * usage:
 34	 *
 35	 * int eval_expr(char *expr, long *result); returns 0 if expression is ok, -1 if
 36	 * bad, -2 if attempted division by zero expr must be null-terminated and can
 37	 * contain whitespace characters (\t \n)
 38	 *
 39	 * -recursion-based -supports arbitrary levels of precedence and parentheses
 40	 * -supports nested unary minus and plus: 3--2 = 3-(-2) = 5
 41	 * -arithmetic operators: +,-,*,/,%,=
 42	 * -26 registers named "a" thru "z", assignment operator =
 43	 * -C-like comparison and logic operators: ==,!=,<,>,<=,>=,&&,||
 44	 *
 45	 */
 46	
 47	#define STANDALONE 0
 48	#define BIGNUM 20                /* largest number taken */
 49	
 50	/* two-char operators */
 51	enum {
 52	  EQUAL, NEQU, GTE, LTE, AND, OR, IDENT
 53	};
 54	
 55	#ifdef DEBUG
 56	#define X(c) (c==IDENT ? '#' :\
 57	              (c==EQUAL ? '=' :\
 58	               (c==AND ? '&' :\
 59	                (c==OR ? '|' :\
 60	                 (c)))))
 61	#endif
 62	
 63	#define TERMINAL(c) (((c)==')' || !(c)) ? 1 : 0)
 64	/* order of precedence (high to low):
 65	   * / %
 66	   + -
 67	   > < == != >= <=
 68	   &&
 69	   ||
 70	   =
 71	 */
 72	#define PRECEDENCE(op) (op=='*' || op=='/' || op=='%' ? 5 :\
 73	                        (op=='+' || op=='-' ? 4 :\
 74	                         (op=='>' || op=='<' || op==EQUAL || op==NEQU\
 75	                                  || op==GTE || op==LTE ? 3 :\
 76	                          (op==AND ? 2 : (op==OR ? 1 : 0)))))
 77	#define SKIP_SPACE(e) while(isspace(*(e))) ++(e)
 78	
 79	/* function prototypes */
 80	#ifdef NEW_STYLE
 81	char   *eval(int prevPrec, long val, char operator, char *expr, long *result);
 82	char   *getreg(char *expr, int regId, long *val);
 83	char   *getval(char *expr, long *val);
 84	char   *getop(char *expr, char *op);
 85	long    calc(long x, long y, int op);
 86	#else
 87	char   *eval();
 88	char   *getreg();
 89	char   *getval();
 90	char   *getop();
 91	long    calc();
 92	#endif
 93	
 94	/* global error flag */
 95	int     evalerr;
 96	
 97	/* registers */
 98	
 99	static long regAr[26];
100	
101	/* kludge to implement several precedence levels - saveOper works like "push back" in token parsers */
102	
103	char    saveOper = 0;
104	
105	/*--------------------*/
106	long
107	calc(x, y, op)
108	  long    x;
109	  long    y;
110	  int     op;
111	{
112	  long    z;
113	
114	  switch (op) {
115	  case '+':
116	    if (evalerr == OK_EXPR && (x > 0 ?
117	                               y > 0 && x > LONG_MAX - y :
118	                               y < 0 && x < LONG_MIN - y ))
119	      evalerr = OVERFLOW;
120	    z = x + y;
121	    break;
122	  case '-':
123	    if (evalerr == OK_EXPR && (x > 0 ?
124	                               y < 0 && x > LONG_MAX + y :
125	                               y > 0 && x < LONG_MIN + y ))
126	      evalerr = OVERFLOW;
127	    z = x - y;
128	    break;
129	  case '/':
130	    if (y == 0) {
131	      evalerr = DIV_ZERO;
132	      z = 0;
133	    } else
134	      z = x / y;
135	    break;
136	  case '*':
137	    if (evalerr == OK_EXPR && x != 0 && y != 0 &&
138	        x != -1 && y != -1 &&    /* LONG_MIN/(-1) causes FP error! */
139		x != 1 && y != 1 &&	/* LONG_MIN/(+1) causes FP error on an Alpha! */
140	        ((x > 0) == (y > 0) ?   /* (even though it shouldn't.) */
141	         LONG_MAX / y / x == 0 :
142	         LONG_MIN / y / x == 0 ))
143	      evalerr = OVERFLOW;
144	    z = x * y;
145	    break;
146	  case '%':
147	    if (y == 0) {
148	      evalerr = DIV_ZERO;
149	      z = 0;
150	    } else
151	      z = x % y;
152	    break;
153	  case AND:
154	    z = x && y;
155	    break;
156	  case OR:
157	    z = x || y;
158	    break;
159	  case EQUAL:
160	    z = x == y;
161	    break;
162	  case NEQU:
163	    z = x != y;
164	    break;
165	  case '<':
166	    z = x < y;
167	    break;
168	  case '>':
169	    z = x > y;
170	    break;
171	  case LTE:
172	    z = x <= y;
173	    break;
174	  case GTE:
175	    z = x >= y;
176	    break;
177	  case IDENT:                        /* the right-identity operator, used for
178	                                 * initial call to eval() */
179	    z = y;
180	    break;
181	  default:
182	    z = 0;
183	    evalerr = BAD_EXPR;
184	  }
185	  return z;
186	}
187	
188	/*--------------------*/
189	char   *
190	getop(expr, oper)
191	  char   *expr;
192	  char   *oper;
193	{
194	  char    ch;
195	  switch (ch = *(expr++)) {
196	  case '&':
197	    if (*(expr++) == '&')
198	      *oper = AND;
199	    break;
200	  case '|':
201	    if (*(expr++) == '|')
202	      *oper = OR;
203	    break;
204	  case '=':
205	    if (*(expr++) == '=')
206	      *oper = EQUAL;
207	    break;
208	  case '!':
209	    if (*(expr++) == '=')
210	      *oper = NEQU;
211	    break;
212	  case '<':
213	    if (*expr == '=') {
214	      ++expr;
215	      *oper = LTE;
216	    } else
217	      *oper = '<';
218	    break;
219	  case '>':
220	    if (*expr == '=') {
221	      ++expr;
222	      *oper = GTE;
223	    } else
224	      *oper = '>';
225	    break;
226	  default:
227	    *oper = ch;
228	    break;
229	  }
230	  return expr;
231	}
232	/*--------------------*/
233	char   *
234	getreg(expr, regId, val)
235	  char   *expr;
236	  int     regId;
237	  long   *val;
238	{
239	  SKIP_SPACE(expr);
240	  if (*expr == '=' && *(expr + 1) != '=') {        /* assignment, not equality */
241	    expr = eval(-1, 0L, IDENT, expr + 1, val);
242	    regAr[regId] = *val;
243	  } else
244	    *val = regAr[regId];
245	  return expr;
246	}
247	
248	/*--------------------*/
249	char   *
250	getval(expr, val)
251	  char   *expr;
252	  long   *val;
253	{
254	  char    buffer[BIGNUM];
255	  int     regId;
256	  int     bufptr = 0;
257	  long    accum;
258	
259	  SKIP_SPACE(expr);
260	  if (*expr == '(') {                /* parenthetical expression */
261	    expr = eval(-1, 0L, IDENT, expr + 1, val);
262	    if (*expr != ')')
263	      evalerr = BAD_EXPR;
264	    return expr + 1;
265	  }
266	  if (*expr == '-') {                /* unary minus */
267	    expr = getval(expr + 1, &accum);
268	    *val = accum * -1;
269	    return expr;
270	  } else if (*expr == '!') {        /* logical NOT */
271	    expr = getval(expr + 1, &accum);
272	    *val = (accum ? 0 : 1);
273	    return expr;
274	  } else if (*expr == '+')        /* unary plus */
275	    return getval(expr + 1, val);
276	  else if (((regId = (int) toupper(*expr)) >= 'A') && (regId <= 'Z'))
277	    return getreg(expr + 1, regId - 'A', val);
278	  else
279	    while (isdigit(*expr) && bufptr < BIGNUM) /* FIXED (?): possible buffer overflow without the bufptr < BIGNUM? */
280	      buffer[bufptr++] = *expr++;
281	  if (bufptr == 0)
282	    evalerr = BAD_EXPR;                /* no digits */
283	  buffer[bufptr] = 0;
284	  sscanf(buffer, "%ld", val); /* FIXME wouldn't it be simpler and more efficient to calculate val directly, ie val = val*10+digitvalueof(*expr++) in the loop? */
285	  return expr;
286	}
287	
288	/*--------------------*/
289	#ifdef NEW_STYLE
290	char   *
291	eval(int prevPrec, long val1, char oper1, char *expr, long *result)
292	#else
293	char   *
294	eval(prevPrec, val1, oper1, expr, result)
295	  int     prevPrec;/* prevPrec is the precedence that ends the subevaluation, ie in 1 && 2+3*4-1 || 0 prevPrec would be prec of && while evaluating 2+3*4-1 */
296	  char    oper1, *expr;
297	  long    val1, *result;
298	#endif
299	{
300	  long    result2, val2;
301	  char    oper2;
302	  int     prec1, prec2;
303	
304	#ifdef DEBUG
305	      fprintf(stderr, "eval prev = %ld, val1 = %ld, op1 = %c \n", prevPrec, val1, X(oper1));
306	#endif
307	
308	  saveOper = 0;
309	
310	  expr = getval(expr, &val2);
311	  SKIP_SPACE(expr);
312	  if (TERMINAL(*expr)) {        /* trivial: expr is number or () */
313	    *result = calc(val1, val2, oper1);
314	    return expr;
315	  }
316	  expr = getop(expr, &oper2);
317	
318	  if ((prec1 = PRECEDENCE(oper1)) >= (prec2 = PRECEDENCE(oper2))) {
319	    if (prec2 > prevPrec /* don't understand this, so I removed it: || prec1 <= prevPrec */) {
320	      /* continue to gobble up expressions */
321	
322	#ifdef DEBUG
323	      fprintf(stderr, "gobble prev = %ld, val1 = %ld, op1 = %c, val2 = %ld, op2 = %c \n", prevPrec, val1, X(oper1), val2, X(oper2));
324	#endif
325	
326	      expr = eval(prevPrec, calc(val1, val2, oper1), oper2, expr, result);/* prec1 -> prevPrec */
327	
328	#ifdef DEBUG
329	      fprintf(stderr, "gobbled (prev %ld) %ld = ((%ld %c %ld) %c ..)\n", prevPrec, *result, val1, X(oper1), val2, X(oper2));
330	#endif
331	
332	    } else {
333	      /* return from subevaluation of terms with higher precedence */
334	      *result = calc(val1, val2, oper1);
335	      saveOper = oper2;/* akin to "push back" in parsers */
336	
337	#ifdef DEBUG
338	      fprintf(stderr, "return (prev %ld, save = %c) %ld = (%ld %c %ld)\n", prevPrec, X(saveOper), *result, val1, X(oper1), val2);
339	#endif
340	
341	    }
342	  } else {
343	
344	#ifdef DEBUG
345	      fprintf(stderr, "subevaluate op2, prev = %ld, val1 = %ld, op1 = %c, val2 = %ld, op2 = %c, saveOp = %c (%ld) \n", prevPrec, val1, X(oper1), val2, X(oper2), X(saveOper), saveOper);
346	#endif
347	
348	    expr = eval(prec1, val2, oper2, expr, &result2);/* start subevaluation starting from val2 op2 */
349	    *result = calc(val1, result2, oper1);
350	
351	#ifdef DEBUG
352	      fprintf(stderr, "returned from subeval, result2 = %ld, result = %ld, prev = %ld, val1 = %ld, op1 = %c, val2 = %ld, op2 = %c, saveOp = %c (%ld) \n", result2, *result, prevPrec, val1, X(oper1), val2, X(oper2), X(saveOper), saveOper);
353	#endif
354	
355	      if (saveOper && PRECEDENCE(saveOper) >= prevPrec) {/* otherwise (if saveOper, but precedence < prevPrec) yet more nested subevalutions to return from */
356	
357	#ifdef DEBUG
358	      fprintf(stderr, "evaluate saveOper, prev = %ld, val1 = %ld, op1 = %c \n", prevPrec, *result , X(saveOper));
359	#endif
360	
361	      expr = eval(prevPrec, *result, saveOper, expr, result);/* prec2 -> prevPrec */
362	
363	#ifdef DEBUG
364	      fprintf(stderr, "return, no more subevals (prev %ld, old Saved: %c (%ld)) %ld = .. ? (%ld %c (%ld %c ..))\n", prevPrec, X(saveOper), saveOper, *result,
365	              val1, X(oper1), val2, X(oper2));
366	#endif
367	
368	      /* saveOper = 0; */ /* FIXED don't erase history, continue if saveOper exists */
369	    }
370	
371	#ifdef DEBUG
372	    else
373	      fprintf(stderr, "return, no saveOp or more subevals (prev %ld, saveOp = %c (%ld)) %ld = (%ld %c (%ld %c ..))\n", prevPrec, X(saveOper), saveOper, *result, val1, X(oper1), val2, X(oper2));
374	#endif
375	
376	  }
377	
378	  return expr;
379	}
