402	int
403	eval_expr(expr, result)                /* wrapper for eval() */
404	  char   *expr;
405	  long   *result;
406	{
407	#ifdef DEBUG
408	      fprintf(stderr, "* eval *\n");
409	#endif
410	  evalerr = OK_EXPR;
411	  if (*eval(-1, 0L, IDENT, expr, result) != 0)
412	    evalerr = BAD_EXPR;                /* still chars left */
413	  return (evalerr);
