434	}
435	#endif

550			 * folded using the write limit because we predec/postinc the cell later.
551			 * (Departure from '94 draft to follow Chip Wendell's CoreWin implementation.)
552			 */
553			#ifdef NEW_MODES
554			if (INDIR_A(IR.B_mode))
555			{
556				IR.B_mode = RAW_MODE(IR.B_mode);
557				#ifdef RWLIMIT
558				if (IR.B_mode != INDIRECT) {
559					tempPtr = &memory[raddrB = addrB];
560				} else
561				#endif
562				{
563					display_read(raddrB); /* INDIRECT -> read from base ofs. cell. */
564				}
565				offsPtr = &(tempPtr->A_value);
566			} else {
567				#ifdef RWLIMIT
568				if (IR.B_mode != (FIELD_T) INDIRECT) {
569					tempPtr = &memory[raddrB = addrB];
570			} else
571				#endif
572				{
573					display_read(raddrB); /* INDIRECT -> read from base ofs cell. */
574				}
575				offsPtr = &(tempPtr->B_value);
576			}
577			temp = *offsPtr;
578	
579			#else /* !NEW_MODES */
580			
581			temp = tempPtr->B_value;
582	
583			#endif /* NEW_MODES */
584	
585			/* For pre-decrement modes, do the decrement now.  */
586			if (IR.B_mode == (FIELD_T) PREDECR)
587			{
588				if (--temp < 0)
589					temp = coreSize1;
590				#ifdef NEW_MODES
591				*offsPtr = temp;
592				#else
593				tempPtr->B_value = temp;
594				#endif
595				display_dec(addrB);
596			}
597	
598			/* Compute the final B-operand's core address. */
599	#ifndef RWLIMIT
600			ADDMOD(temp, addrB, addrB);
601	#else
602			addrB = foldw(addrB + temp);
603			raddrB = foldr(raddrB + temp);
604	#endif
605			/* Read the B-register values. */
606			#ifdef NEW_MODES
607			AB_Value = memory[raddrB].A_value;
608			#endif
609			IR.B_value = memory[raddrB].B_value;
610	
611			/* For postincrement modes, do the increment now. */
612			if (IR.B_mode == (FIELD_T) POSTINC)
613			{
614				if (++temp == coreSize)
615					temp = 0;
616				#ifdef NEW_MODES
617				*offsPtr = temp;
618				#else
619				tempPtr->B_value = temp;
620				#endif
621				display_inc(tempPtr - &memory[0]);
622			}
623		} else
624		{
625	
626		#ifdef NEW_MODES
627		AB_Value = tempPtr->A_value;
628		IR.B_value = tempPtr->B_value;
629		#else
630		IR.B_value = temp = tempPtr->B_value;
631		#endif
632		}
633	} else {
634	      addrB = progCnt;
635	      raddrB = progCnt;
636	      IR.B_value = memory[addrB].B_value;
637	      AB_Value = memory[addrB].A_value;
638	}
